DROP DATABASE IF EXISTS ecommerce;
CREATE DATABASE ecommerce;
USE ecommerce;
SET FOREIGN_KEY_CHECKS=0;
CREATE TABLE categories (category_id INT PRIMARY KEY, category_name VARCHAR(60) NOT NULL, parent_category_id INT, FOREIGN KEY (parent_category_id) REFERENCES categories(category_id));
CREATE TABLE brands (brand_id INT PRIMARY KEY, brand_name VARCHAR(60) NOT NULL, country VARCHAR(40));
CREATE TABLE suppliers (supplier_id INT PRIMARY KEY, supplier_name VARCHAR(80) NOT NULL, city VARCHAR(40), contact_email VARCHAR(100), rating DECIMAL(3,1));
CREATE TABLE employees (employee_id INT PRIMARY KEY, employee_name VARCHAR(80) NOT NULL, manager_id INT, department VARCHAR(40), salary DECIMAL(10,2), hire_date DATE, FOREIGN KEY (manager_id) REFERENCES employees(employee_id));
CREATE TABLE customers (customer_id INT PRIMARY KEY, first_name VARCHAR(40), last_name VARCHAR(40), email VARCHAR(100), phone VARCHAR(20), gender VARCHAR(10), birth_date DATE, city VARCHAR(40), state VARCHAR(40), signup_date DATE, loyalty_tier VARCHAR(10), referred_by INT, is_active TINYINT, FOREIGN KEY (referred_by) REFERENCES customers(customer_id));
CREATE TABLE products (product_id INT PRIMARY KEY, product_name VARCHAR(120) NOT NULL, category_id INT, brand_id INT, supplier_id INT, price DECIMAL(10,2), cost_price DECIMAL(10,2), stock_qty INT, weight_kg DECIMAL(6,2), created_at DATETIME, is_active TINYINT, description VARCHAR(255), FOREIGN KEY (category_id) REFERENCES categories(category_id), FOREIGN KEY (brand_id) REFERENCES brands(brand_id), FOREIGN KEY (supplier_id) REFERENCES suppliers(supplier_id));
CREATE TABLE coupons (coupon_id INT PRIMARY KEY, code VARCHAR(20) NOT NULL, discount_type VARCHAR(10), discount_value DECIMAL(8,2), start_date DATE, end_date DATE, min_order_value DECIMAL(10,2));
CREATE TABLE orders (order_id INT PRIMARY KEY, customer_id INT NOT NULL, order_date DATETIME, order_status VARCHAR(20), coupon_id INT, shipping_city VARCHAR(40), sales_channel VARCHAR(20), handled_by INT, FOREIGN KEY (customer_id) REFERENCES customers(customer_id), FOREIGN KEY (coupon_id) REFERENCES coupons(coupon_id), FOREIGN KEY (handled_by) REFERENCES employees(employee_id));
CREATE TABLE order_items (order_item_id INT PRIMARY KEY, order_id INT NOT NULL, product_id INT NOT NULL, quantity INT, unit_price DECIMAL(10,2), discount_pct DECIMAL(5,2), FOREIGN KEY (order_id) REFERENCES orders(order_id), FOREIGN KEY (product_id) REFERENCES products(product_id));
CREATE TABLE payments (payment_id INT PRIMARY KEY, order_id INT NOT NULL, payment_method VARCHAR(20), payment_status VARCHAR(15), amount DECIMAL(12,2), payment_date DATETIME, FOREIGN KEY (order_id) REFERENCES orders(order_id));
CREATE TABLE shipments (shipment_id INT PRIMARY KEY, order_id INT NOT NULL, courier VARCHAR(30), shipped_date DATE, delivered_date DATE, shipment_status VARCHAR(20), FOREIGN KEY (order_id) REFERENCES orders(order_id));
CREATE TABLE reviews (review_id INT PRIMARY KEY, product_id INT NOT NULL, customer_id INT NOT NULL, rating INT, review_text VARCHAR(255), review_date DATE, FOREIGN KEY (product_id) REFERENCES products(product_id), FOREIGN KEY (customer_id) REFERENCES customers(customer_id));
CREATE TABLE returns (return_id INT PRIMARY KEY, order_item_id INT NOT NULL, return_date DATE, reason VARCHAR(60), refund_amount DECIMAL(12,2), FOREIGN KEY (order_item_id) REFERENCES order_items(order_item_id));
CREATE TABLE inventory_log (log_id INT PRIMARY KEY, product_id INT NOT NULL, change_qty INT, change_type VARCHAR(20), log_date DATETIME, FOREIGN KEY (product_id) REFERENCES products(product_id));
SET FOREIGN_KEY_CHECKS=1;
